css:
.ataa-print { direction: rtl; text-align: right; font-family: "IBM Plex Sans Arabic", Tahoma, Arial, sans-serif; color: #1f2937; }
.ataa-print h1 { color: #AD8F52; font-size: 22px; margin: 0 0 4px; }
.ataa-print .muted { color: #6b7280; font-size: 11px; }
.ataa-print table.kv { width: 100%; border-collapse: collapse; margin: 14px 0; }
.ataa-print table.kv td { padding: 7px 8px; border-bottom: 1px solid #e5e7eb; font-size: 13px; }
.ataa-print table.kv td.k { color: #6b7280; width: 35%; }
.ataa-print .amount { font-size: 20px; font-weight: 700; }
.ataa-print .head { display: flex; justify-content: space-between; align-items: flex-start; border-bottom: 3px solid #AD8F52; padding-bottom: 10px; }
.ataa-print .qr { text-align: center; }
.ataa-print .qr img { width: 110px; height: 110px; }
.ataa-print .gift { border: 2px solid #AD8F52; border-radius: 14px; padding: 28px; text-align: center; }
.ataa-print .gift blockquote { border: 0; margin: 16px auto; max-width: 80%; font-size: 15px; color: #374151; }
.ataa-print .stamp { color: #b91c1c; border: 2px solid #b91c1c; display: inline-block; padding: 2px 10px; font-weight: 700; }
